sop:
@c1 syntax.clause form=imperative verb="distribute" complement=$n1
@n1 syntax.nominal head="Start"
@r1 syntax.relation marker="with" from=$n1 to=$n2
@n2 syntax.nominal head="axis" dependent="horizontal"
@k1 syntax.coordination conjunction="then" conjunct=$c1 conjunct=$c2
